// Original vector character art. Breed silhouettes and markings are shared by cards and battle sprites.
const BREED_COATS={Labrador:'#dfb87b',Beagle:'#b77949','Cocker Spaniel':'#b97743','Golden Retriever':'#e7b85e',Schnauzer:'#8b97a6',Poodle:'#f0dfc6','German Shepherd':'#bb915f','Australian Shepherd':'#8d9ba9','Border Collie':'#303744','Cosmic Border Collie':'#34364f','Domestic Shorthair':'#a1adb9',Ragdoll:'#eee2cf','British Shorthair':'#8494aa','Maine Coon':'#b58965',Burmese:'#99705a',Bengal:'#d5a269',Abyssinian:'#b98755',Siamese:'#e8dbc4','Oriental Shorthair':'#666e83','Cosmic Siamese':'#e1d4eb'};
HEROES.forEach(h=>{h.colour=BREED_COATS[h.breed]||h.colour});
const artCircle=(x,y,r,fill,stroke='none',width=0)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="${width}"/>`;
const artEllipse=(x,y,rx,ry,fill)=>`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${fill}"/>`;
function artEyes(left='#724a2d',right=left,wide=false){return [84,138].map((x,i)=>`<ellipse cx="${x}" cy="94" rx="${wide?12:11}" ry="14" fill="#fff7ec" stroke="#343342" stroke-width="3"/>${artEllipse(x+1,95,7,10,i?right:left)}${artEllipse(x+1,96,3.5,7,'#262b36')}${artCircle(x-2,90,2.7,'#ffffff')}`).join('')}
function dogMuzzle(fill='#f6e8d0',long=false){return `${artEllipse(111,long?122:119,long?23:30,long?23:20,fill)}<path d="M100 ${long?115:111}Q111 ${long?108:104} 122 ${long?115:111}Q121 ${long?124:120} 111 ${long?126:123}Q101 ${long?124:120} 100 ${long?115:111}Z" fill="#343340"/><path d="M111 123V131Q100 141 92 132M111 131Q123 141 130 131" fill="none" stroke="#53404a" stroke-width="3" stroke-linecap="round"/><path d="M104 137Q112 145 120 136L118 146Q110 153 105 145Z" fill="#e7a1a6"/>`}
function breedHeadGear(h){if(h.gear==='crown'||h.gear==='cosmic')return `<path d="M89 48L82 24 100 31 111 15 122 31 141 24 135 48Z" fill="${h.gear==='cosmic'?'#b7f0ef':'#f5d27a'}" stroke="#6a5364" stroke-width="3"/><path d="M106 33L111 25 117 33 111 41Z" fill="${h.gear==='cosmic'?'#9c86d6':'#b18cd5'}"/>${h.gear==='cosmic'?'<path d="M182 56l4 8 9 3-9 4-4 8-3-8-9-4 9-3Z" fill="#c9f9eb"/>':''}`;if(h.gear==='professor')return '<path d="M79 47L111 34 146 47 112 59Z" fill="#736394" stroke="#3d3654" stroke-width="3"/><path d="M146 47V72" stroke="#efd28b" stroke-width="3"/>';return ''}
function cartoonDog(h){const b=h.breed,c=h.colour,ink='#343442';let ears='',head='',marks='',fur='',eyes=artEyes(),muzzle=dogMuzzle(),details='';
if(b==='Poodle'){
ears=`<path d="M64 72Q39 66 35 98Q26 132 49 145Q75 149 75 117M156 72Q181 66 186 98Q195 132 172 145Q146 149 146 117" fill="#d6bfa8" stroke="${ink}" stroke-width="4"/>`;
head=`<path d="M77 67Q111 47 145 67L143 114Q134 148 111 150Q87 148 79 117Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;
fur=[[64,56,17],[80,44,18],[101,39,20],[125,39,20],[146,46,17],[158,61,16],[45,88,14],[43,111,15],[49,132,15],[174,88,14],[177,111,15],[170,132,15]].map(([x,y,r])=>artCircle(x,y,r,'#f1e6d6',ink,3.5)).join('');
details='<path d="M64 48q10-9 18 0M93 34q10-8 17 1M125 33q10-6 17 4M39 105q9-7 15 1M168 122q8-7 15 0" fill="none" stroke="#cdbba6" stroke-width="3" stroke-linecap="round"/>';eyes=artEyes('#735541');muzzle=dogMuzzle('#f8eddd',true);
}else if(b.includes('Border Collie')){
ears=`<path d="M63 82L49 27Q71 24 91 59M131 59Q152 25 174 27L163 85" fill="${c}" stroke="${ink}" stroke-width="4"/><path d="M59 39L66 69 80 60M163 39L156 69 143 60" fill="#cba5aa"/><path d="M49 27L48 49 60 43M174 27L178 48 164 43" fill="${c}"/>`;
head=`<path d="M65 71Q83 51 111 52Q141 50 159 70L167 103 156 113 164 120 148 123 146 136 128 147 111 150 93 145 76 135 75 124 59 121 67 111 56 104Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;
marks='<path d="M103 53L117 53 121 72 117 89 129 111 137 129 111 149 84 129 94 111 105 88 101 71Z" fill="#f6f4e9"/><path d="M76 126L85 128 91 142 111 150 129 143 140 128 148 126 144 145 111 161 81 146Z" fill="#f3f1e7" stroke="#343442" stroke-width="2"/>';eyes=artEyes('#8c6744');muzzle=dogMuzzle('#fff6e8',true);details='<path d="M72 78Q83 72 94 77M127 77Q139 72 150 78" fill="none" stroke="#757b84" stroke-width="3"/>';
}else if(b==='Schnauzer'){
ears=`<path d="M68 72L51 38 81 48 91 72M131 72L142 48 172 38 155 80" fill="#657180" stroke="${ink}" stroke-width="4"/><path d="M51 38L48 64 65 58M172 38L175 64 158 58" fill="#a3a9b2" stroke="${ink}" stroke-width="3"/>`;
head=`<path d="M66 74Q77 52 111 53Q146 52 157 74L158 119 141 144 81 144 64 119Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;
marks='<path d="M79 107L66 121 73 129 68 140 85 139 91 155 111 160 131 155 137 139 154 140 148 129 155 121 143 107Z" fill="#d8dce0" stroke="#657180" stroke-width="3"/>';eyes=artEyes('#735345');muzzle='<path d="M109 111Q94 102 77 111L68 126 86 123 99 128 111 119 123 128 136 123 154 126 145 111Q128 102 113 111Z" fill="#edf0ed"/><path d="M101 110Q111 104 122 110L119 119 111 124 103 119Z" fill="#343442"/><path d="M111 124V139M91 133L96 145M130 133L125 145" fill="none" stroke="#929ba4" stroke-width="3"/>';details='<path d="M69 79L96 74 101 86 76 90ZM121 86L126 74 153 79 146 90Z" fill="#e5e7e3"/>';
}else if(b==='German Shepherd'){
ears=`<path d="M65 79L54 16Q78 19 96 63M126 63Q145 19 168 16L158 80" fill="#3c4046" stroke="${ink}" stroke-width="4"/><path d="M64 33L71 65 87 61M159 33L151 65 135 61" fill="#c99487"/>`;
head=`<path d="M64 78L80 57 111 52 144 57 159 78 154 116 137 139 111 153 85 139 67 116Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M80 57L111 52 144 57 137 81 111 95 86 81Z" fill="#4b4a48"/><path d="M89 110L111 98 134 110 141 130 111 151 81 130Z" fill="#494745"/>';eyes=artEyes('#8a653a');muzzle=dogMuzzle('#605649',true);details='<path d="M74 78L95 76 97 83 78 87M125 83L128 76 149 78 145 87" fill="#e8bc7a"/>';
}else if(b==='Australian Shepherd'){
ears=`<path d="M64 80L48 35 84 46 94 71M130 71L140 46 176 35 158 82" fill="#4c5869" stroke="${ink}" stroke-width="4"/><path d="M48 35L47 65 67 56M176 35L178 65 158 56" fill="#8596a8" stroke="${ink}" stroke-width="3"/>`;
head=`<path d="M67 70Q87 50 111 52Q140 50 158 70L168 102 157 115 165 120 149 127 147 139 111 155 76 139 75 127 59 120 66 113 55 102Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M69 71L88 57 99 68 90 88 67 91ZM139 63L157 75 152 95 136 89ZM64 107L80 102 88 117 71 123ZM139 115L158 110 151 129 135 131Z" fill="#596779"/><path d="M103 52L117 52 120 85 130 113 139 138 111 155 84 138 93 112 104 84Z" fill="#f0eee5"/>';eyes=artEyes('#78b5d2','#8e6749');muzzle=dogMuzzle('#faf0de',true);details='<path d="M73 79L95 77 96 84 77 88M126 84L127 77 149 79 145 88" fill="#d9ad79"/>';
}else if(b==='Cocker Spaniel'){
ears=`<path d="M70 68Q37 58 30 99L31 138Q40 164 61 150L81 101M150 68Q184 58 191 99L190 138Q181 164 160 150L140 101" fill="#8e5634" stroke="${ink}" stroke-width="4"/><path d="M46 85Q35 113 44 143M58 84Q45 116 55 143M174 85Q185 113 176 143M162 84Q175 116 165 143" fill="none" stroke="#ba7c4c" stroke-width="4" stroke-linecap="round"/>`;
head=`<path d="M67 79Q65 48 109 48Q155 45 156 79L150 121Q136 146 111 150Q84 146 72 121Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M79 62Q83 37 101 49Q110 29 122 48Q141 35 145 61" fill="#d79c60"/>';eyes=artEyes('#68432b',undefined,true);muzzle=dogMuzzle('#e6b581');
}else if(b==='Golden Retriever'){
ears=`<path d="M70 66Q41 55 34 88L39 112 34 120 52 128 70 116 84 76M150 66Q179 55 186 88L181 112 186 120 168 128 150 116 136 76" fill="#d09b42" stroke="${ink}" stroke-width="4"/>`;
head=`<path d="M66 78Q69 49 111 49Q153 48 157 78L161 103 151 114 157 120 144 126 137 141 111 149 84 141 78 127 64 120 70 113 61 103Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M83 65Q108 43 138 65L128 69 111 63 95 70Z" fill="#f5d18b"/>';muzzle=dogMuzzle('#fae0a3');eyes=artEyes('#79532d');details='<path d="M72 81Q84 74 96 81M127 81Q140 74 151 81" fill="none" stroke="#f7d99b" stroke-width="5" stroke-linecap="round"/>';
}else if(b==='Beagle'){
ears=`<path d="M68 68Q36 60 33 90L37 126Q45 145 62 135L82 84M153 68Q184 60 188 90L184 126Q176 145 159 135L139 84" fill="#9b6139" stroke="${ink}" stroke-width="4"/>`;
head=`<path d="M65 78Q72 49 111 50Q153 49 158 78L156 117Q142 147 111 151Q78 147 65 117Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M72 62Q91 44 111 50Q137 46 151 64L139 75 123 71 111 65 97 73 81 75Z" fill="#4a4340"/><path d="M106 51L115 51 119 88 135 115 140 136 111 151 82 136 87 114 104 88Z" fill="#f8eedb"/>';muzzle=dogMuzzle('#fff5e2');eyes=artEyes('#835231');details='<path d="M73 80L94 78M128 78L150 80" stroke="#ddb17c" stroke-width="5" stroke-linecap="round"/>';
}else{
ears=`<path d="M71 67Q40 61 35 87L44 119Q53 132 66 118L83 82M150 67Q181 61 186 87L177 119Q168 132 155 118L137 82" fill="#c1945b" stroke="${ink}" stroke-width="4"/>`;head=`<path d="M64 79Q67 49 111 49Q155 49 158 79L156 114Q143 145 111 149Q78 145 66 114Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;marks='<path d="M77 65Q111 47 145 65" fill="none" stroke="#f5d69e" stroke-width="5" stroke-linecap="round"/>';eyes=artEyes('#735033');muzzle=dogMuzzle('#f6dbab');
}
return `<g data-breed-art="${b}" stroke-linejoin="round">${ears}${head}${marks}${fur}${eyes}${muzzle}${details}${breedHeadGear(h)}</g>`}
function cartoonCat(h){const b=h.breed,c=h.colour,ink='#343442',pointed=['Siamese','Cosmic Siamese','Ragdoll'].includes(b),oriental=b==='Oriental Shorthair',maine=b==='Maine Coon',british=b==='British Shorthair',dark=b==='Cosmic Siamese'?'#756485':b==='Ragdoll'?'#8e8b91':'#665247';
const ears=`<path d="M62 80L${oriental?30:maine?43:48} ${oriental?20:maine?17:29}Q79 27 94 62M128 62Q149 27 ${oriental?192:maine?179:174} ${oriental?20:maine?17:29}L161 84" fill="${pointed?dark:c}" stroke="${ink}" stroke-width="4"/><path d="M${oriental?43:60} 39L70 69 83 59M${oriental?178:161} 39L151 69 139 59" fill="#d6a5a7"/>${maine?'<path d="M43 17L44 4 56 24M179 17L180 4 168 24" fill="none" stroke="#5d514e" stroke-width="4"/>':''}`;
const head=oriental?`<path d="M65 73Q112 48 158 73L151 107 130 133 111 149 92 133 70 107Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`:maine?`<path d="M62 75Q80 49 111 52Q143 48 161 75L170 108 158 118 169 126 150 129 149 143 130 146 111 158 93 148 74 143 72 130 54 126 64 116 53 106Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`:`<path d="M61 80Q70 48 111 50Q154 48 163 80L163 113Q154 145 111 152Q68 146 59 114Z" fill="${c}" stroke="${ink}" stroke-width="4"/>`;
let marks='',eyes='#8eb48c';if(pointed){marks=`<path d="M67 75Q81 57 111 64Q142 57 156 75L155 108Q141 140 111 146Q82 140 66 108Z" fill="${dark}"/>`;if(b==='Ragdoll')marks+='<path d="M111 65L99 91 79 121 91 140 111 151 132 140 144 121 124 91Z" fill="#f8f0e1"/>';eyes='#7bb8dc'}else if(b==='Bengal'){marks=[[72,75],[151,76],[67,108],[154,111],[87,61],[137,61]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="7" ry="6" fill="#e1ba84" stroke="#805335" stroke-width="4"/>`).join('');marks+='<path d="M103 54L111 67 119 54" fill="none" stroke="#8a603d" stroke-width="4"/>';eyes='#94ae69'}else if(b==='Domestic Shorthair'||maine){marks='<path d="M97 55L101 72 111 63 121 72 125 55M63 93L75 99M62 109L76 113M159 93L147 99M160 109L146 113" fill="none" stroke="#63707a" stroke-width="4" stroke-linecap="round"/>';eyes=maine?'#a8b57b':'#83af98'}else if(british){eyes='#d49b56';marks=artEllipse(75,117,19,16,'#b3bdc9')+artEllipse(147,117,19,16,'#b3bdc9')}else if(b==='Burmese'){eyes='#d6b36a';marks=artEllipse(111,114,30,25,'#80604f')}else if(b==='Abyssinian'){eyes='#9eb07a';marks='<path d="M98 54L104 72 111 63 118 72 125 54" fill="none" stroke="#8d593b" stroke-width="4"/>'}else if(oriental)eyes='#a9c58e';
const muzzle=`${artEllipse(100,120,15,13,pointed?'#d5c3b7':'#f1e3d0')}${artEllipse(122,120,15,13,pointed?'#d5c3b7':'#f1e3d0')}<path d="M104 112Q111 108 118 112L111 119Z" fill="#b87c84" stroke="${ink}" stroke-width="2"/><path d="M111 119V126Q103 134 96 128M111 126Q120 134 126 128" fill="none" stroke="#66505a" stroke-width="2.5" stroke-linecap="round"/><path d="M80 118L44 113M81 127L43 131M142 118L178 113M141 127L179 131" stroke="#f5e8d5" stroke-width="2.5" stroke-linecap="round"/>`;
return `<g data-breed-art="${b}" stroke-linejoin="round">${ears}${head}${marks}${artEyes(eyes)}${muzzle}${breedHeadGear(h)}</g>`}
function petFace(h){return h.species==='dog'?cartoonDog(h):cartoonCat(h)}
const avatarSprites=new Map();
function getAvatarSprite(h){if(typeof window.Image!=='function')return null;if(!avatarSprites.has(h.id)){const img=new window.Image();img.decoding='async';img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(heroSVG(h.id));avatarSprites.set(h.id,img)}return avatarSprites.get(h.id)}
function initBreedArt(){getAvatarSprite(ensureAvatar())}
function breedLineup(species){return `<section class="breed-lineup"><div><h3>Meet the breeds</h3><p>Tap a portrait to preview its cartoon design.</p></div><div class="breed-portraits">${HEROES.filter(h=>h.species===species).map(h=>`<button data-breed-preview="${h.id}" aria-label="Preview ${h.breed}">${petPortrait(h)}<span>${h.breed}</span></button>`).join('')}</div></section>`}
function previewBreed(id){const h=HEROES.find(h=>h.id===id);if(!h)return;getAvatarSprite(h);openModal(`${topModal('MEET YOUR COMPANION')}<div class="breed-preview">${heroSVG(h.id)}<span class="tag">RANK ${h.rank} · ${h.title.toUpperCase()}</span><h2 id="modal-title">${h.breed}</h2><p>${h.name} · ${canSelectAvatar(h)?'Available in your avatar ladder':'Unlocks at player level '+h.level}</p><div class="pet-stats"><span>♥ ${h.hp} base life</span><span>ϟ ${h.damage} attack</span><span>✦ ${h.superDamage} super</span></div><div class="modal-actions"><button class="primary" data-action="close">Back to avatars →</button></div></div>`)}
function drawBreedAvatar(c,g){const image=getAvatarSprite(g.hero);if(!image?.complete||!image.naturalWidth)return false;const bob=g.moving?Math.sin(g.elapsed*15)*1.8:Math.sin(g.elapsed*3);c.save();c.translate(g.x,g.y);ellipse(c,0,26,33,12,'#203b3f55');c.strokeStyle='#d5fa5980';c.lineWidth=3;c.beginPath();c.ellipse(0,26,36,16,0,0,7);c.stroke();if(g.invincible>0){c.strokeStyle='#bbf6ee80';c.beginPath();c.arc(0,0,43,0,7);c.stroke()}c.drawImage(image,-49,-82+bob,98,112);if(g.zaps>0){ellipse(c,40,-5,8,8,'#edffc4');ellipse(c,40,-5,4,4,'#ffffff')}c.fillStyle='#fbf8ef';c.textAlign='center';c.font='800 12px sans-serif';c.shadowColor='#29354a';c.shadowBlur=4;c.fillText(g.hero.name,0,-83);c.shadowBlur=0;c.restore();return true}
